export type Variant="primary"|"secondary"|"danger";export function classes(variant:Variant,extra?:string):string{return ["btn","btn--"+variant,extra].filter(Boolean).join(" ");}export function buttonType(type:"button"|"submit"|"reset"|undefined):"button"|"submit"|"reset"{return type??"button";}export function safeRel(target:string|undefined,rel:string|undefined):string|undefined{if(target!=="_blank")return rel;return [...new Set([...(rel??"").split(/\s+/).filter(token=>token&&token!=="opener"),"noopener"])].join(" ");}
type Own={variant?:Variant};export type ButtonProps=Own&((ComponentPropsWithRef<"button">&{as?:"button";href?:never})|(Omit<ComponentPropsWithRef<"a">,"href">&{as:"a";href:string;disabled?:never}));export function Button(props:ButtonProps){if(props.as==="a"){const {as,variant="primary",className,target,rel,...rest}=props;return <a {...rest} target={target} rel={safeRel(target,rel)} className={classes(variant,className)}/>;}const {as,variant="primary",className,type,...rest}=props;return <button {...rest} type={buttonType(type)} className={classes(variant,className)}/>;}

export function parseTicketId(raw:string|undefined):number|null {
  if(raw===undefined||! /^[1-9]\d*$/.test(raw))return null;
  const id=Number(raw);return Number.isSafeInteger(id)?id:null;
}
export type TicketTab="activity"|"history";
export function ticketPath(id:number,tab?:TicketTab):string {
  if(!Number.isSafeInteger(id)||id<1)throw new RangeError("Niepoprawne ID");
  return "/tickets/"+id+(tab?"/"+tab:"");
}

