function channel(value:number){
  const c=value/255;
  return c<=0.04045?c/12.92:((c+0.055)/1.055)**2.4;
}

export function luminance(hex:string){
  if(!/^#[0-9a-f]{6}$/i.test(hex))throw Error("Kolor w postaci #rrggbb");
  const [r,g,b]=[1,3,5].map(at=>channel(parseInt(hex.slice(at,at+2),16)));
  return 0.2126*r+0.7152*g+0.0722*b;
}

export function contrast(a:string,b:string){
  const [high,low]=[luminance(a),luminance(b)].sort((x,y)=>y-x);
  return (high+0.05)/(low+0.05);
}

export function meetsAA(foreground:string,background:string,{large=false}:{large?:boolean}={}){
  return contrast(foreground,background)>=(large?3:4.5);
}

import {createContext,useCallback,useContext,useState,type ReactNode} from "react";

const AnnounceContext=createContext<(message:string)=>void>(()=>{});

export function Announcer({children}:{children:ReactNode}){
  const [message,setMessage]=useState("");
  const [alertMessage,setAlertMessage]=useState("");
  const announce=useCallback((text:string)=>{
    setAlertMessage("");
    setMessage("");
    requestAnimationFrame(()=>setMessage(text));
  },[]);
  const announceError=useCallback((text:string)=>{
    setAlertMessage("");
    requestAnimationFrame(()=>setAlertMessage(text));
  },[]);
  return (
    <AnnounceContext.Provider value={announce}>
      <ErrorContext.Provider value={announceError}>
        {children}
        <div role="status" aria-live="polite" className="visually-hidden">{message}</div>
        <div role="alert" className="visually-hidden">{alertMessage}</div>
      </ErrorContext.Provider>
    </AnnounceContext.Provider>
  );
}

const ErrorContext=createContext<(message:string)=>void>(()=>{});
