export type ThemeChoice=Theme|"system";
export function resolveTheme(choice:ThemeChoice,systemDark:boolean):Theme{return choice==="system"?(systemDark?"dark":"light"):choice;}
export function nextTheme(theme:Theme):Theme{return theme==="light"?"dark":"light";}
export function applyChoice(root:HTMLElement,choice:ThemeChoice):void{if(choice==="system")delete root.dataset.theme;else root.dataset.theme=choice;}
