export function addToCart(cart:Cart,product:Product):Cart{if(!product.inStock)return cart;return {...cart,[product.id]:(cart[product.id]??0)+1};}
export function cartCount(cart:Cart):number{return Object.values(cart).reduce<number>((sum,count)=>sum+(count??0),0);}
