export type Ticket={id:number;title:string;description:string;priority:"LOW"|"MEDIUM"|"CRITICAL";assignee:string|null;tags:string[];status:"OPEN"|"DONE";createdAt:string};
export type NewValues=Pick<Ticket,"title"|"description"|"priority"|"assignee">&{tags?:readonly string[]};
export const empty=():NewValues=>({title:"",description:"",priority:"MEDIUM",assignee:null,tags:[]});
export function nextId(existing:readonly Ticket[]):number{const max=existing.reduce((max,ticket)=>{if(!Number.isSafeInteger(ticket.id)||ticket.id<0)throw new RangeError("Niepoprawne ID");return Math.max(max,ticket.id);},0);if(max>=Number.MAX_SAFE_INTEGER)throw new RangeError("Brak bezpiecznego ID");return max+1;}
