export const STATUSES=["NEW","PAID","SHIPPED","CANCELLED"] as const;export type Status=(typeof STATUSES)[number];export type Currency="PLN"|"EUR";export type Order={id:number;customer:string;totalGrosze:number;status:Status;createdAt:string};export type HistoryEntry={orderId:number;from:Status;to:Status;at:string};export const TRANSITIONS:Record<Status,readonly Status[]>={NEW:["PAID","CANCELLED"],PAID:["SHIPPED","CANCELLED"],SHIPPED:[],CANCELLED:[]};export function canTransition(from:Status,to:Status):boolean{return TRANSITIONS[from].includes(to);}
export function planTransition(orders:readonly Order[],ids:readonly number[],to:Status){const unique=new Set(ids);const affected=orders.filter(order=>unique.has(order.id)&&canTransition(order.status,to));const changedIds=new Set(affected.map(order=>order.id));return {affected,skippedIds:[...unique].filter(id=>!changedIds.has(id))};}
export type State={orders:readonly Order[];history:readonly HistoryEntry[];selectedIds:ReadonlySet<number>;lastBulk:{previous:ReadonlyArray<{id:number;status:Status}>;historyCount:number}|null;lastResult:{to:Status;changedIds:readonly number[];skippedIds:readonly number[]}|null};export type Action={type:"selectionToggled";id:number}|{type:"visibleSelectionChanged";ids:readonly number[];checked:boolean}|{type:"bulkTransitioned";ids:readonly number[];to:Status;at:string}|{type:"bulkUndone"};
export function init(orders:readonly Order[]):State{return {orders:orders.map(order=>({...order})),history:[],selectedIds:new Set<number>(),lastBulk:null,lastResult:null};}
export function ordersReducer(state:State,action:Action):State{switch(action.type){case "selectionToggled":{const selectedIds=new Set(state.selectedIds);if(selectedIds.has(action.id))selectedIds.delete(action.id);else if(state.orders.some(order=>order.id===action.id))selectedIds.add(action.id);return {...state,selectedIds};}case "visibleSelectionChanged":{const selectedIds=new Set(state.selectedIds);const existing=new Set(state.orders.map(order=>order.id));for(const id of action.ids){if(action.checked&&existing.has(id))selectedIds.add(id);else selectedIds.delete(id);}return {...state,selectedIds};}case "bulkTransitioned":{if(!Number.isFinite(Date.parse(action.at)))throw Error("Niepoprawna data akcji");const plan=planTransition(state.orders,action.ids,action.to);const changedIds=new Set(plan.affected.map(order=>order.id));const entries=plan.affected.map(order=>({orderId:order.id,from:order.status,to:action.to,at:action.at}));return {...state,orders:state.orders.map(order=>changedIds.has(order.id)?{...order,status:action.to}:order),history:[...entries,...state.history],selectedIds:new Set<number>(),lastBulk:plan.affected.length?{previous:plan.affected.map(order=>({id:order.id,status:order.status})),historyCount:entries.length}:state.lastBulk,lastResult:{to:action.to,changedIds:[...changedIds],skippedIds:plan.skippedIds}};}case "bulkUndone":{if(!state.lastBulk)return state;const previous=new Map(state.lastBulk.previous.map(item=>[item.id,item.status]));return {...state,orders:state.orders.map(order=>{const status=previous.get(order.id);return status===undefined?order:{...order,status};}),history:state.history.slice(state.lastBulk.historyCount),selectedIds:new Set<number>(),lastBulk:null,lastResult:null};}default:{const exhaustive:never=action;throw Error(JSON.stringify(exhaustive));}}}
export function filterOrders(orders:readonly Order[],query:string,status:Status|"ALL"):Order[]{const q=query.trim().toLocaleLowerCase("pl-PL");return orders.filter(order=>(status==="ALL"||order.status===status)&&order.customer.toLocaleLowerCase("pl-PL").includes(q));}
export function statusCounts(orders:readonly Order[]):Record<Status|"ALL",number>{return {ALL:orders.length,NEW:orders.filter(order=>order.status==="NEW").length,PAID:orders.filter(order=>order.status==="PAID").length,SHIPPED:orders.filter(order=>order.status==="SHIPPED").length,CANCELLED:orders.filter(order=>order.status==="CANCELLED").length};}
export function formatMoney(grosze:number,currency:Currency):string{if(!Number.isSafeInteger(grosze)||grosze<0)throw RangeError("Kwota");const amount=currency==="PLN"?grosze/100:grosze/430;return new Intl.NumberFormat("pl-PL",{style:"currency",currency}).format(amount);}
export function makeOrders():Order[]{const customers=["Lumen sp. z o.o.","Jan Kowalski","Orbis S.A.","Maria Wiśniewska","Zenit"];return Array.from({length:30},(_,i)=>({id:1000+i,customer:customers[i%customers.length],totalGrosze:9900+(i*4721)%250000,status:STATUSES[i%STATUSES.length],createdAt:new Date(Date.UTC(2026,9,1+i%20)).toISOString()}));}
