export function appendEvent(events:readonly LiveEvent[],event:LiveEvent,limit=10):LiveEvent[]{if(!Number.isSafeInteger(limit)||limit<1)throw RangeError("Limit");return [event,...events.filter(previous=>previous.id!==event.id)].slice(0,limit);}
console.log(appendEvent([{id:1,text:"A"}],{id:2,text:"B"},1).length);

