import {isRouteErrorResponse} from "react-router";export type ErrorView={title:string;detail:string;action:"list"|"login"|"retry"};
export function errorView(error:unknown):ErrorView{if(isRouteErrorResponse(error)){switch(error.status){case 400:return {title:"Niepoprawny adres",detail:"Sprawdź numer ticketu.",action:"list"};case 401:return {title:"Zaloguj się ponownie",detail:"Sesja nie pozwala otworzyć tego widoku.",action:"login"};case 403:return {title:"Brak dostępu",detail:"Nie masz uprawnień do tego widoku.",action:"list"};case 404:return {title:"Nie znaleziono ticketu",detail:"Wróć do listy i wybierz dostępny rekord.",action:"list"};case 429:return {title:"Zbyt wiele prób",detail:"Odczekaj przed ponownym żądaniem.",action:"list"};}}return {title:"Nie udało się wczytać strony",detail:"Spróbuj ponownie. Jeśli problem wróci, skontaktuj się z pomocą.",action:"retry"};}
export function safeReturn(raw:string|null){if(!raw||!raw.startsWith("/")||raw.startsWith("//")||raw.includes("\\"))return "/tickets";try{const url=new URL(raw,"https://devdesk.example");return url.origin==="https://devdesk.example"&&url.pathname!=="/login"?url.pathname+url.search:"/tickets";}catch{return "/tickets";}}
export function loginPath(returnTo:string){return "/login?"+new URLSearchParams({redirect:safeReturn(returnTo)}).toString();}
console.log(safeReturn("/tickets/42?tab=notes"));

