export type Item={readonly ticketId:number;readonly note:string};export type State={readonly items:readonly Item[]};export type Action={type:"add";ticketId:number}|{type:"remove";ticketId:number}|{type:"note";ticketId:number;note:string}|{type:"clear"};export const initial:State={items:[]};export function reducer(state:State,action:Action):State{if(action.type==="clear")return state.items.length?{items:[]}:state;if(!Number.isSafeInteger(action.ticketId)||action.ticketId<1)throw RangeError("Niepoprawne ID");switch(action.type){case "add":return state.items.some(item=>item.ticketId===action.ticketId)?state:{items:[...state.items,{ticketId:action.ticketId,note:""}]};case "remove":return state.items.some(item=>item.ticketId===action.ticketId)?{items:state.items.filter(item=>item.ticketId!==action.ticketId)}:state;case "note":{const note=action.note.slice(0,500);const old=state.items.find(item=>item.ticketId===action.ticketId);return !old||old.note===note?state:{items:state.items.map(item=>item.ticketId===action.ticketId?{...item,note}:item)};}}}export const selectCount=(state:State)=>state.items.length;export const selectItem=(id:number)=>(state:State)=>state.items.find(item=>item.ticketId===id);export type Owner="local"|"subtree"|"url"|"server"|"client-global";export type Requirement={serverOwned?:boolean;shareableView?:boolean;oneComponent?:boolean;nearbyOnly?:boolean};export function chooseOwner(requirement:Requirement):Owner{if(requirement.serverOwned)return "server";if(requirement.shareableView)return "url";if(requirement.oneComponent)return "local";if(requirement.nearbyOnly)return "subtree";return "client-global";}
const one=reducer(initial,{type:"add",ticketId:1});const two=reducer(one,{type:"add",ticketId:2});const noted=reducer(two,{type:"note",ticketId:1,note:"API"});
