import {useState} from "react";

export function Counter(){
  const [count,setCount]=useState(0);
  function onClick(){
    setCount(count+1);
    setCount(count+1);
    setCount(count+1);
  }
  return <button onClick={onClick}>{count}</button>;
}

import {useState} from "react";

export function Counter(){
  const [count,setCount]=useState(0);
  function onClick(){
    setCount(value=>value+1);
    setCount(value=>value+1);
    setCount(value=>value+1);
  }
  return <button onClick={onClick}>{count}</button>;
}

import {useEffect,useState} from "react";

export function List({filter}:{filter:string}){
  const [items,setItems]=useState<string[]>([]);
  useEffect(()=>{
    fetch("/api/items?f="+filter).then(r=>r.json()).then(setItems);
  },[]);
  return <p>{items.length}</p>;
}

import {memo,useState} from "react";

const Row=memo(function Row({onSelect}:{onSelect:()=>void}){
  return <button onClick={onSelect}>Wybierz</button>;
});

export function Table(){
  const [selected,setSelected]=useState(0);
  return <><p>{selected}</p><Row onSelect={()=>setSelected(1)}/></>;
}

export function Field(){
  return <div><label>E-mail</label><input/></div>;
}

export function Link({url}:{url:string}){
  return <a href={url}>Otwórz</a>;
}

import {useState} from "react";

export function Cart(){
  const [items,setItems]=useState<number[]>([]);
  const [total,setTotal]=useState(0);
  function add(price:number){
    setItems([...items,price]);
    setTotal(total+price);
  }
  return <button onClick={()=>add(1)}>{total}</button>;
}

import {useEffect,useState} from "react";

export function Clock(){
  const [tick,setTick]=useState(0);
  useEffect(()=>{
    setInterval(()=>setTick(value=>value+1),1000);
  },[]);
  return <p>{tick}</p>;
}

import {useState} from "react";

export function Tags(){
  const [tags,setTags]=useState<string[]>([]);
  function add(tag:string){
    tags.push(tag);
    setTags(tags);
  }
  return <button onClick={()=>add("a")}>{tags.length}</button>;
}

type Ticket={id:number};

export async function load(){
  const response=await fetch("/api/ticket");
  return (await response.json()) as Ticket;
}

import {useState} from "react";

type Ticket={id:number};

export function Details(){
  const [ticket]=useState<Ticket|null>(null);
  return <p>{ticket?.id??"brak"}</p>;
}

type Action={type:"add";text:string}|{type:"remove";id:number};

export function reducer(state:string[],action:Action){
  switch(action.type){
    case "add":return [...state,action.text];
    case "remove":return state.filter((_,i)=>i!==action.id);
  }
}
